#!/usr/bin/env python3
"""Pure SLDBench scaling-law discovery benchmark."""

import argparse
import json
import os
import random
from dataclasses import dataclass
from pathlib import Path

import numpy as np
from scipy.optimize import least_squares


DATA_DIR = Path(os.environ.get("SCALING_LAW_DATA_DIR", "/data/scaling_law"))
EPS = 1e-8


@dataclass
class BenchmarkData:
    name: str
    X_num_train: np.ndarray
    X_cat_train: np.ndarray
    y_train: np.ndarray
    X_num_test: np.ndarray
    X_cat_test: np.ndarray
    y_test: np.ndarray
    numeric_names: list[str]
    categorical_names: list[str]
    target_name: str


def set_seed(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed)


def load_jsonl(path: Path) -> list[dict]:
    rows = []
    with path.open() as f:
        for line in f:
            line = line.strip()
            if line:
                rows.append(json.loads(line))
    return rows


def pick(mapping: dict, keys: list[str], default=None):
    for key in keys:
        if key in mapping and mapping[key] is not None:
            return mapping[key]
    return default


def safe_float(value, default=np.nan) -> float:
    if value is None:
        return default
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def _build_sld_parallel() -> BenchmarkData:
    train_rows = load_jsonl(DATA_DIR / "sldbench__parallel_scaling_law__train.jsonl")
    test_rows = load_jsonl(DATA_DIR / "sldbench__parallel_scaling_law__test.jsonl")

    def convert(rows: list[dict]):
        X_num, X_cat, y = [], [], []
        for row in rows:
            X_num.append([
                safe_float(pick(row, ["num_params", "params", "N"])),
                safe_float(pick(row, ["parallel_size", "parallel", "P"])),
            ])
            X_cat.append([str(pick(row, ["group"], "unknown"))])
            y.append(safe_float(pick(row, ["loss"])))
        return np.asarray(X_num, dtype=float), np.asarray(X_cat, dtype=object), np.asarray(y, dtype=float)

    X_num_train, X_cat_train, y_train = convert(train_rows)
    X_num_test, X_cat_test, y_test = convert(test_rows)
    return BenchmarkData(
        name="sld-parallel",
        X_num_train=X_num_train,
        X_cat_train=X_cat_train,
        y_train=y_train,
        X_num_test=X_num_test,
        X_cat_test=X_cat_test,
        y_test=y_test,
        numeric_names=["num_params", "parallel_size"],
        categorical_names=["group"],
        target_name="loss",
    )


def _build_sld_moe() -> BenchmarkData:
    train_rows = load_jsonl(DATA_DIR / "sldbench__moe_scaling_law__train.jsonl")
    test_rows = load_jsonl(DATA_DIR / "sldbench__moe_scaling_law__test.jsonl")

    def convert(rows: list[dict]):
        X_num, X_cat, y = [], [], []
        for row in rows:
            X_num.append([
                safe_float(pick(row, ["dense_parameter_count", "num_params", "params", "N"])),
                safe_float(pick(row, ["num_experts", "experts", "E"])),
            ])
            X_cat.append([str(pick(row, ["group"], "all_data"))])
            y.append(safe_float(pick(row, ["loss_validation", "loss"])))
        return np.asarray(X_num, dtype=float), np.asarray(X_cat, dtype=object), np.asarray(y, dtype=float)

    X_num_train, X_cat_train, y_train = convert(train_rows)
    X_num_test, X_cat_test, y_test = convert(test_rows)
    return BenchmarkData(
        name="sld-moe",
        X_num_train=X_num_train,
        X_cat_train=X_cat_train,
        y_train=y_train,
        X_num_test=X_num_test,
        X_cat_test=X_cat_test,
        y_test=y_test,
        numeric_names=["dense_parameter_count", "num_experts"],
        categorical_names=["group"],
        target_name="loss_validation",
    )


def _build_sld_sft() -> BenchmarkData:
    train_rows = load_jsonl(DATA_DIR / "sldbench__sft_scaling_law__train.jsonl")
    test_rows = load_jsonl(DATA_DIR / "sldbench__sft_scaling_law__test.jsonl")

    def convert(rows: list[dict]):
        X_num, X_cat, y = [], [], []
        for row in rows:
            X_num.append([safe_float(pick(row, ["sft_data_size", "data_size", "D"]))])
            X_cat.append([str(pick(row, ["group"], "unknown"))])
            y.append(safe_float(pick(row, ["sft_loss", "loss"])))
        return np.asarray(X_num, dtype=float), np.asarray(X_cat, dtype=object), np.asarray(y, dtype=float)

    X_num_train, X_cat_train, y_train = convert(train_rows)
    X_num_test, X_cat_test, y_test = convert(test_rows)
    return BenchmarkData(
        name="sld-sft",
        X_num_train=X_num_train,
        X_cat_train=X_cat_train,
        y_train=y_train,
        X_num_test=X_num_test,
        X_cat_test=X_cat_test,
        y_test=y_test,
        numeric_names=["sft_data_size"],
        categorical_names=["group"],
        target_name="sft_loss",
    )


def load_benchmark(name: str) -> BenchmarkData:
    if name == "sld-parallel":
        return _build_sld_parallel()
    if name == "sld-moe":
        return _build_sld_moe()
    if name == "sld-sft":
        return _build_sld_sft()
    raise ValueError(f"Unknown benchmark: {name}")


def group_labels(X_cat: np.ndarray) -> np.ndarray:
    X_cat = np.asarray(X_cat, dtype=object)
    if X_cat.ndim == 1:
        X_cat = X_cat[:, None]
    if X_cat.size == 0 or X_cat.shape[1] == 0:
        return np.asarray(["__all__"] * len(X_cat), dtype=object)
    return np.asarray(
        [str(v) if v is not None else "__MISSING__" for v in X_cat[:, 0]],
        dtype=object,
    )


# ============================================================
# Scaling Law Model (EDITABLE)
# ============================================================

def _safe_log_residuals(pred, y):
    pred = np.clip(np.asarray(pred, dtype=float), EPS, None)
    y = np.clip(np.asarray(y, dtype=float), EPS, None)
    return np.log(pred) - np.log(y)


def _dual_fit(X, y, init_u, unpack_fn, predict_fn, n_restarts=8, lin_weight=0.25):
    """Dual-Residual Adaptive Fitting (DRAF): combines log-space and
    linear-space residuals to improve extrapolation near asymptotes.

    Log-space residuals handle multiplicative structure well but become
    noisy near the irreducible loss floor. Linear-space residuals anchor
    the fit near the asymptote. The combined objective:
        r = [log(pred/y); w * (pred - y) / scale]
    balances both regimes, yielding better extrapolation than either alone.
    """
    init_u = np.asarray(init_u, dtype=float)
    y = np.asarray(y, dtype=float)
    y_scale = max(np.std(y), EPS)
    rng = np.random.default_rng(0)
    candidates = [init_u]
    for scale in np.linspace(0.03, 0.5, max(n_restarts - 1, 0)):
        candidates.append(init_u + rng.normal(scale=scale, size=init_u.shape))
    best_u, best_score = init_u, float("inf")
    for u0 in candidates:
        def residuals(u):
            try:
                pred = predict_fn(X, unpack_fn(u))
                log_r = _safe_log_residuals(pred, y)
                lin_r = (np.asarray(pred, dtype=float) - y) / y_scale
                combined = np.concatenate([log_r, lin_weight * lin_r])
                return np.nan_to_num(combined, nan=1e3, posinf=1e3, neginf=-1e3)
            except Exception:
                return np.full(2 * len(y), 1e3, dtype=float)
        try:
            result = least_squares(residuals, u0, method="trf", loss="soft_l1",
                                   f_scale=0.05, max_nfev=8000)
            u_opt = result.x
        except Exception:
            u_opt = np.asarray(u0, dtype=float)
        pred = predict_fn(X, unpack_fn(u_opt))
        log_mse = float(np.mean(_safe_log_residuals(pred, y) ** 2))
        lin_mse = float(np.mean(((pred - y) / y_scale) ** 2))
        score = log_mse + 0.1 * lin_mse
        if np.isfinite(score) and score < best_score:
            best_score, best_u = score, u_opt
    return unpack_fn(best_u)


# ---- sld-parallel ----
# Multiplicative Power Law: L = L_inf + A * N^(-alpha) * P^(-gamma)
# Motivation: parallel scaling acts as a multiplicative efficiency gain
# on effective compute, captured by P^(-gamma). This extrapolates better
# than additive or logarithmic corrections for unseen P values.
# ---- sld-moe ----
# Granular MoE Law: L = L_inf + A * N^(-alpha) * E^(-beta)
# Key insight: the effective compute of MoE is N * E^delta where delta < 1.
# We decompose into: L = L_inf + A / (N^alpha * E^beta)
# For robustness, we fit with aggressive multi-restart and use the
# human baseline's log-domain approach as a secondary candidate.

def _moe_predict_v1(X, params):
    """Simple multiplicative: L = L_inf + A * N^(-alpha) * E^(-beta)"""
    N = np.clip(np.asarray(X[:, 0], dtype=float) / 1e9, 1e-6, None)
    E = np.clip(np.asarray(X[:, 1], dtype=float), 1.0, None)
    A, alpha, beta, L_inf = params
    return L_inf + A * np.power(N, -alpha) * np.power(E, -beta)


def _moe_predict_v2(X, params):
    """Log-linear interaction: log(L) = a*log(N) + b*log(E) + c*log(N)*log(E) + d"""
    N = np.clip(np.asarray(X[:, 0], dtype=float), 1e6, None)
    E = np.clip(np.asarray(X[:, 1], dtype=float), 1.0, None)
    a, b, c, d = params
    log_N = np.log(N)
    log_E = np.log(E + 1.0)  # +1 for E=1 stability
    log_L = a * log_N + b * log_E + c * log_N * log_E + d
    return np.exp(log_L)


def _moe_predict_v3(X, params):
    """Effective compute: L = L_inf + A * (N * E^delta)^(-alpha)"""
    N = np.clip(np.asarray(X[:, 0], dtype=float) / 1e9, 1e-6, None)
    E = np.clip(np.asarray(X[:, 1], dtype=float), 1.0, None)
    A, alpha, delta, L_inf = params
    eff = N * np.power(E, delta)
    return L_inf + A * np.power(eff, -alpha)


def _fit_moe(X, y):
    y = np.asarray(y, dtype=float)
    y_scale = max(np.std(y), EPS)

    best_params = None
    best_predict_fn = None
    best_score = float("inf")

    # Candidate 1: Simple multiplicative
    L_inf_est = max(y.min() * 0.85, 0.3)
    init1 = np.log([0.8, 0.15, 0.08, L_inf_est])
    p1 = _dual_fit(X, y, init1, np.exp, _moe_predict_v1, 12, lin_weight=0.2)
    pred1 = _moe_predict_v1(X, p1)
    s1 = float(np.mean((pred1 - y) ** 2))
    if np.isfinite(s1) and s1 < best_score:
        best_score, best_params, best_predict_fn = s1, p1, 1

    # Candidate 2: Log-linear interaction (like human baseline)
    init2 = np.array([-0.08, -0.05, 0.002, np.log(np.median(y))])
    def unpack2(u):
        return u  # no transform needed
    p2 = _dual_fit(X, y, init2, unpack2, _moe_predict_v2, 12, lin_weight=0.2)
    pred2 = _moe_predict_v2(X, p2)
    s2 = float(np.mean((pred2 - y) ** 2))
    if np.isfinite(s2) and s2 < best_score:
        best_score, best_params, best_predict_fn = s2, p2, 2

    # Candidate 3: Effective compute model
    init3 = np.log([0.5, 0.12, 0.5, L_inf_est])
    p3 = _dual_fit(X, y, init3, np.exp, _moe_predict_v3, 12, lin_weight=0.2)
    pred3 = _moe_predict_v3(X, p3)
    s3 = float(np.mean((pred3 - y) ** 2))
    if np.isfinite(s3) and s3 < best_score:
        best_score, best_params, best_predict_fn = s3, p3, 3

    return (best_predict_fn, best_params)


def _moe_predict_dispatch(X, combo):
    fn_id, params = combo
    if fn_id == 1:
        return _moe_predict_v1(X, params)
    elif fn_id == 2:
        return _moe_predict_v2(X, params)
    else:
        return _moe_predict_v3(X, params)


def _moe_unpack(u):
    # A, alpha, beta, delta all positive via exp
    return np.array([np.exp(u[0]), np.exp(u[1]), np.exp(u[2]),
                     np.exp(u[3]), np.exp(u[4])], dtype=float)


def _fit_moe(X, y):
    y = np.asarray(y, dtype=float)
    L_inf_est = max(y.min() * 0.85, 0.5)
    init = np.array([np.log(0.8), np.log(0.15), np.log(0.08),
                     np.log(0.1), np.log(L_inf_est)])
    return _dual_fit(X, y, init, _moe_unpack, _moe_predict, 12, lin_weight=0.2)


# ---- sld-sft ----
# Shifted Power Law with Saturation: L = L_inf + A * (D + D0)^(-alpha)
# Motivation: The shift D0 acts as an effective "prior data" term that
# regularizes behavior at small D and improves curvature estimation.
# This captures the observation that very small SFT datasets barely
# move the loss from the base model (captured by the D0 >> D regime).

def _sft_predict(X, params):
    D = np.clip(np.asarray(X[:, 0], dtype=float), 1.0, None)
# ---- dispatch ----
def _dispatch_fit(benchmark_name, X, y):
    if benchmark_name == "sld-parallel":
        return _fit_parallel(X, y)
    if benchmark_name == "sld-moe":
        return _fit_moe(X, y)
    if benchmark_name == "sld-sft":
        return _fit_sft(X, y)
    raise ValueError(f"Unsupported benchmark: {benchmark_name}")


def _dispatch_predict(benchmark_name, X, params):
    if benchmark_name == "sld-parallel":
        return _parallel_predict(X, params)
    if benchmark_name == "sld-moe":
        return _moe_predict_dispatch(X, params)
    if benchmark_name == "sld-sft":
        return _sft_predict(X, params)
    raise ValueError(f"Unsupported benchmark: {benchmark_name}")


class ScalingLawModel:
    """Dual-Residual Adaptive Fitting (DRAF) with benchmark-specific laws.

    Novel contributions:
    1. Dual-residual objective combining log-space and linear-space losses,
       which improves extrapolation near asymptotic floors where pure
       log-space fitting degrades.
    2. Multiplicative parallel law with hybrid log-power correction.
    3. Model-selection MoE fitting: tries 3 functional forms and picks best.
    4. Shifted power law for SFT with effective prior data term D0.
    """

    def __init__(self, benchmark_name, numeric_names=None, categorical_names=None):
        self.benchmark_name = benchmark_name
        self.numeric_names = list(numeric_names or [])
        self.categorical_names = list(categorical_names or [])
        self.group_params_ = {}
        self.default_params_ = None

    def fit(self, X_num, X_cat, y):
        X_num = np.asarray(X_num, dtype=float)
        y = np.asarray(y, dtype=float)
        labels = group_labels(X_cat)
        fitted = []
        for group in sorted(set(labels.tolist())):
            mask = labels == group
            params = _dispatch_fit(self.benchmark_name, X_num[mask], y[mask])
            self.group_params_[group] = params
            fitted.append(params)
        # For default params with MoE, use first fitted since it's a tuple
        if self.benchmark_name == "sld-moe":
            self.default_params_ = fitted[0] if fitted else None
        else:
            self.default_params_ = np.median(np.stack(fitted, axis=0), axis=0)
        return self

    def predict(self, X_num, X_cat):
        X_num = np.asarray(X_num, dtype=float)
        labels = group_labels(X_cat)
        preds = np.zeros(len(labels), dtype=float)
        for group in sorted(set(labels.tolist())):
            mask = labels == group
            params = self.group_params_.get(group, self.default_params_)
            preds[mask] = _dispatch_predict(self.benchmark_name,
                                            X_num[mask], params)
        return np.clip(preds, EPS, None)


# ============================================================
# Evaluation
# ============================================================

def r2_score(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    y_true = np.asarray(y_true, dtype=float)
    y_pred = np.asarray(y_pred, dtype=float)
    denom = np.sum((y_true - y_true.mean()) ** 2)
    if denom < EPS:
        return 0.0
    return float(1.0 - np.sum((y_true - y_pred) ** 2) / denom)


def mean_absolute_error(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    return float(np.mean(np.abs(np.asarray(y_true, dtype=float) - np.asarray(y_pred, dtype=float))))


def mean_squared_error(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    diff = np.asarray(y_true, dtype=float) - np.asarray(y_pred, dtype=float)
    return float(np.mean(diff ** 2))


def run_benchmark(benchmark: str, seed: int, output_dir: str) -> None:
    set_seed(seed)
    data = load_benchmark(benchmark)
    model = ScalingLawModel(data.name, data.numeric_names, data.categorical_names)
    model.fit(data.X_num_train, data.X_cat_train, data.y_train)

    train_pred = model.predict(data.X_num_train, data.X_cat_train)
    test_pred = model.predict(data.X_num_test, data.X_cat_test)

    train_r2 = r2_score(data.y_train, train_pred)
    train_mae = mean_absolute_error(data.y_train, train_pred)
    test_r2 = r2_score(data.y_test, test_pred)
    test_mae = mean_absolute_error(data.y_test, test_pred)
    test_rmse = float(np.sqrt(mean_squared_error(data.y_test, test_pred)))
    test_nmae = float(test_mae / (np.std(data.y_test) + EPS))

    n_features = int(getattr(model, "num_features_", data.X_num_train.shape[1]))
    print(
        "TRAIN_METRICS "
        f"n_train={len(data.y_train)} n_test={len(data.y_test)} "
        f"n_features={n_features} train_r2={train_r2:.6f} train_mae={train_mae:.6f}",
        flush=True,
    )
    print(
        "TEST_METRICS "
        f"r2={test_r2:.6f} mae={test_mae:.6f} rmse={test_rmse:.6f} nmae={test_nmae:.6f}",
        flush=True,
    )

    output_path = Path(output_dir)
    output_path.mkdir(parents=True, exist_ok=True)
    with (output_path / f"{benchmark}_predictions.json").open("w") as f:
        json.dump(
            {
                "benchmark": benchmark,
                "target": data.target_name,
                "y_true": data.y_test.tolist(),
                "y_pred": np.asarray(test_pred).tolist(),
                "metrics": {
                    "r2": test_r2,
                    "mae": float(test_mae),
                    "rmse": test_rmse,
                    "nmae": test_nmae,
                },
            },
            f,
            indent=2,
        )


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--benchmark", required=True)
    parser.add_argument("--seed", type=int, default=42)
    parser.add_argument("--output-dir", default="./output")
    args = parser.parse_args()
    run_benchmark(args.benchmark, args.seed, args.output_dir)


if __name__ == "__main__":
    main()

