# ============================================================
# Scaling Law Model (EDITABLE)
# ============================================================

class ScalingLawModel:
    """Improved scaling law with robust fitting and per-group coefficients."""

    def __init__(s, b, n=None, c=None):
        s.benchmark_name = b
        s.numeric_names = list(n or [])
        s.categorical_names = list(c or [])
        s.p_ = {}
        s.d_ = None
        s.num_features_ = len(s.numeric_names)

    def fit(s, X_num, X_cat, y):
        from scipy.optimize import least_squares
        import numpy as np
        X = np.asarray(X_num, float)
        y = np.asarray(y, float)
        L = group_labels(X_cat)

        def _fg(Xg, yg):
            bn = s.benchmark_name
            if bn == "sld-vocab":
                def pred(X, p):
                    n, v, d = np.maximum(X[:, 0], 1), np.maximum(X[:, 1], 1), np.maximum(X[:, 2], 1)
                    return p[0] + p[1] * n ** -p[2] + p[3] * v ** -p[4] + p[5] * d ** -p[6] + p[7] * v ** -p[8] * d ** -p[9]
                def unpack(u):
                    return np.array([u[0], np.exp(u[1]), np.exp(u[2]), np.exp(u[3]), np.exp(u[4]), np.exp(u[5]), np.exp(u[6]), np.exp(u[7]), np.exp(u[8]), np.exp(u[9])])
                ys = max(float(yg.max() - yg.min()), 0.1)
                m = np.median(yg)
                init = np.array([m, np.log(ys), np.log(0.08), np.log(ys), np.log(0.3), np.log(ys), np.log(0.3), np.log(ys * 0.5), np.log(0.3), np.log(0.3)])
                inits = [init]
            elif bn == "sld-lrbsz":
                def pred(X, p):
                    lr = np.maximum(X[:, 0], 1e-12)
                    bsz = np.maximum(X[:, 1], 1)
                    d = np.maximum(X[:, 2], 1)
                    n = np.maximum(X[:, 3], 1)
                    A, aa, B, bb, C, D_lr, E, F, gg, zz, G, ee = p
                    l0 = F * n ** gg * d ** zz
                    b0 = G * d ** ee
                    return A * d ** -aa + B * n ** -bb + C + D_lr * (lr - l0) ** 2 + E * (np.log(bsz) + b0 / bsz)
                def unpack(u):
                    return np.array([np.exp(u[0]), np.exp(u[1]), np.exp(u[2]), np.exp(u[3]), u[4], np.exp(u[5]), np.exp(u[6]), np.exp(u[7]), u[8], u[9], np.exp(u[10]), u[11]])
                # Multiple inits: paper params + data-driven
                p1 = np.array([np.log(262), np.log(0.27), np.log(7.0), np.log(0.075), 0.0, np.log(1279), np.log(0.05), np.log(0.32), -1.06, 0.65, np.log(0.03), 0.35])
                ys = max(float(yg.max() - yg.min()), 0.1)
                ym = float(yg.min())
                p2 = np.array([np.log(ys), np.log(0.25), np.log(ys), np.log(0.1), ym, np.log(500), np.log(0.05), np.log(0.3), -0.8, 0.5, np.log(0.03), 0.3])
                p3 = np.array([np.log(ys), np.log(0.2), np.log(ys), np.log(0.15), ym, np.log(2000), np.log(0.03), np.log(0.25), -1.2, 0.7, np.log(0.02), 0.4])
                inits = [p1, p2, p3]
            else:
                def pred(X, p):
                    u = np.maximum(X[:, 0], 1)
                    n = np.maximum(X[:, 1], 1)
                    d = np.maximum(X[:, 2], 1)
                    de = np.maximum(u * (1 - np.exp(-np.clip(d / u, 0, 50))), 1)
                    return p[0] + p[1] * n ** -p[2] + p[3] * de ** -p[4]
                def unpack(u):
                    return np.exp(u)
                ys = max(float(yg.max() - yg.min()), 0.1)
                init = np.array([np.log(max(yg.min() * 0.9, 0.1)), np.log(ys), np.log(0.35), np.log(ys), np.log(0.35)])
                inits = [init]

            def resid(u):
                try:
                    return (pred(Xg, unpack(u)) - yg).flatten()
                except Exception:
                    return np.full_like(yg, 1e3)

            rng = np.random.default_rng(0)
            best_u, best_s = inits[0].copy(), float("inf")
            for init0 in inits:
                for j in range(8):
                    u0 = init0 + rng.normal(scale=0.15 * (0.5 ** max(j - 2, 0)), size=init0.shape) if j > 0 else init0.copy()
                    try:
                        r = least_squares(resid, u0, method="trf", loss="soft_l1", f_scale=0.05, max_nfev=5000)
                        u_opt = r.x
                    except Exception:
                        u_opt = u0.copy()
                    s_ = float(np.mean((pred(Xg, unpack(u_opt)) - yg) ** 2))
                    if np.isfinite(s_) and s_ < best_s:
                        best_s, best_u = s_, u_opt
            return unpack(best_u)

        fitted = [_fg(X[L == g], y[L == g]) for g in sorted(set(L))]
        s.p_ = {g: fitted[i] for i, g in enumerate(sorted(set(L)))}
        s.d_ = np.median(np.stack(fitted, axis=0), axis=0) if fitted else None
        return s

    def predict(s, X_num, X_cat):
        import numpy as np
        X = np.asarray(X_num, float)
        L = group_labels(X_cat)
        r = np.zeros(len(L), float)
        bn = s.benchmark_name
        for g in sorted(set(L)):
            m = L == g
            p = s.p_.get(g, s.d_)
            if bn == "sld-vocab":
                n, v, d = np.maximum(X[m, 0], 1), np.maximum(X[m, 1], 1), np.maximum(X[m, 2], 1)
                r[m] = p[0] + p[1] * n ** -p[2] + p[3] * v ** -p[4] + p[5] * d ** -p[6] + p[7] * v ** -p[8] * d ** -p[9]
            elif bn == "sld-lrbsz":
                lr = np.maximum(X[m, 0], 1e-12)
                bsz = np.maximum(X[m, 1], 1)
                d = np.maximum(X[m, 2], 1)
                n = np.maximum(X[m, 3], 1)
                A, aa, B, bb, C, D_lr, E, F, gg, zz, G, ee = p
                l0 = F * n ** gg * d ** zz
                b0 = G * d ** ee
                r[m] = A * d ** -aa + B * n ** -bb + C + D_lr * (lr - l0) ** 2 + E * (np.log(bsz) + b0 / bsz)
            else:
                u = np.maximum(X[m, 0], 1)
                n = np.maximum(X[m, 1], 1)
                d = np.maximum(X[m, 2], 1)
                de = np.maximum(u * (1 - np.exp(-np.clip(d / u, 0, 50))), 1)
                r[m] = p[0] + p[1] * n ** -p[2] + p[3] * de ** -p[4]
        return r


# ============================================================
# Evaluation
# ============================================================

def r2_score(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    y_true = np.asarray(y_true, dtype=float)
    y_pred = np.asarray(y_pred, dtype=float)
    denom = np.sum((y_true - y_true.mean()) ** 2)
    if denom < EPS:
        return 0.0
    return float(1.0 - np.sum((y_true - y_pred) ** 2) / denom)


def mean_absolute_error(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    return float(np.mean(np.abs(np.asarray(y_true, dtype=float) - np.asarray(y_pred, dtype=float))))


def mean_squared_error(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    diff = np.asarray(y_true, dtype=float) - np.asarray(y_pred, dtype=float)
    return float(np.mean(diff ** 2))


def run_benchmark(benchmark: str, seed: int, output_dir: str) -> None:
    set_seed(seed)
    data = load_benchmark(benchmark)
    model = ScalingLawModel(data.name, data.numeric_names, data.categorical_names)
    model.fit(data.X_num_train, data.X_cat_train, data.y_train)

    train_pred = model.predict(data.X_num_train, data.X_cat_train)
    test_pred = model.predict(data.X_num_test, data.X_cat_test)

    train_r2 = r2_score(data.y_train, train_pred)
    train_mae = mean_absolute_error(data.y_train, train_pred)
    test_r2 = r2_score(data.y_test, test_pred)
    test_mae = mean_absolute_error(data.y_test, test_pred)
    test_rmse = float(np.sqrt(mean_squared_error(data.y_test, test_pred)))
    test_nmae = float(test_mae / (np.std(data.y_test) + EPS))

    n_features = int(getattr(model, "num_features_", data.X_num_train.shape[1]))
    print(
        "TRAIN_METRICS "
        f"n_train={len(data.y_train)} n_test={len(data.y_test)} "
        f"n_features={n_features} train_r2={train_r2:.6f} train_mae={train_mae:.6f}",
        flush=True,
    )
    print(
        "TEST_METRICS "
        f"r2={test_r2:.6f} mae={test_mae:.6f} rmse={test_rmse:.6f} nmae={test_nmae:.6f}",
        flush=True,
    )

    output_path = Path(output_dir)
    output_path.mkdir(parents=True, exist_ok=True)
    with (output_path / f"{benchmark}_predictions.json").open("w") as f:
        json.dump(
            {
                "benchmark": benchmark,
                "target": data.target_name,
                "y_true": data.y_test.tolist(),
                "y_pred": np.asarray(test_pred).tolist(),
                "metrics": {
                    "r2": test_r2,
                    "mae": float(test_mae),
                    "rmse": test_rmse,
                    "nmae": test_nmae,
                },
            },
            f,
            indent=2,
        )


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--benchmark", required=True)
    parser.add_argument("--seed", type=int, default=42)
    parser.add_argument("--output-dir", default="./output")
    args = parser.parse_args()
    run_benchmark(args.benchmark, args.seed, args.output_dir)


if __name__ == "__main__":
    main()

