# ---- Bottleneck-renormalized vocab law ---------------------------------
# Vocabulary mostly acts by diluting data efficiency rather than changing
# the asymptotic floor. We therefore learn a vocab-dependent renormalization
# of usable data, plus a small residual vocab term.

def _vocab_predict(X, params):
    n = np.clip(np.asarray(X[:, 0], dtype=float), 1.0, None)
    v = np.clip(np.asarray(X[:, 1], dtype=float), 1.0, None)
    d = np.clip(np.asarray(X[:, 2], dtype=float), 1.0, None)
    E, A, alpha, B, beta, phi, C, gamma = params
    d_eff = np.maximum(d / np.power(v, phi), 1.0)
    return E + A * np.power(n, -alpha) + B * np.power(d_eff, -beta) + C * np.power(v, -gamma)



def _fit_vocab(X, y):
    y = np.asarray(y, dtype=float)

    def unpack(u):
        return np.array([
            u[0],
            np.exp(u[1]), np.exp(u[2]),
            np.exp(u[3]), np.exp(u[4]), np.exp(u[5]),
            u[6], np.exp(u[7]),
        ], dtype=float)

    init = np.array([
        float(np.median(y)),
        np.log(max(np.std(y), 0.1)), np.log(0.12),
        np.log(max(np.std(y), 0.1)), np.log(0.32), np.log(0.22),
        0.0, np.log(0.35),
    ], dtype=float)
    return _fit_generic(X, y, init, unpack, _vocab_predict, n_restarts=8, use_log=False)


# ---- Coupled lr/batch optimizer-manifold law ---------------------------
# We fit a resource-dependent reference batch size and a learning-rate optimum
# that bends with departures from that batch. The batch penalty is asymmetric:
# too-small batches are more harmful than too-large ones.

def _lrbsz_predict(X, params):
    lr = np.clip(np.asarray(X[:, 0], dtype=float), 1e-12, None)
    bsz = np.clip(np.asarray(X[:, 1], dtype=float), 1e-12, None)
    d = np.clip(np.asarray(X[:, 2], dtype=float), 1.0, None)
    n = np.clip(np.asarray(X[:, 3], dtype=float), 1.0, None)
    E, A, alpha, B, beta, K_lr, K_b, llr0, gamma, zeta, lbsz0, eta, theta, rho = params
    logn = np.log(n)
    logd = np.log(d)
    logb = np.log(bsz)
    log_lr0 = llr0 + gamma * logn + zeta * logd
    log_b0 = lbsz0 + eta * logn + theta * logd
    batch_offset = logb - log_b0
    lr_offset = np.log(lr) - log_lr0 - rho * batch_offset
    batch_pen = batch_offset + np.exp(-batch_offset) - 1.0  # minimum 0 at b=b0
    return E + A * np.power(n, -alpha) + B * np.power(d, -beta) + K_lr * (lr_offset ** 2) + K_b * batch_pen



def _fit_lrbsz(X, y):
    y = np.asarray(y, dtype=float)
    lr = np.clip(np.asarray(X[:, 0], dtype=float), 1e-12, None)
    bsz = np.clip(np.asarray(X[:, 1], dtype=float), 1.0, None)
    logn = np.log(np.clip(np.asarray(X[:, 3], dtype=float), 1.0, None))
    logd = np.log(np.clip(np.asarray(X[:, 2], dtype=float), 1.0, None))

    def unpack(u):
        return np.array([
            np.exp(u[0]),
            np.exp(u[1]), np.exp(u[2]),
            np.exp(u[3]), np.exp(u[4]),
            np.exp(u[5]), np.exp(u[6]),
            u[7], u[8], u[9],
            u[10], u[11], u[12],
            np.tanh(u[13]),
        ], dtype=float)

    med_log_lr = float(np.median(np.log(lr)))
    med_log_b = float(np.median(np.log(bsz)))
    init = np.array([
        np.log(max(y.min() * 0.95, 0.1)),
        np.log(max(y.max() - y.min(), 0.1)), np.log(0.25),
        np.log(max(y.max() - y.min(), 0.1)), np.log(0.25),
        np.log(50.0), np.log(0.08),
        med_log_lr + 0.9 * float(np.median(logn)) - 0.55 * float(np.median(logd)),
        -0.9, 0.55,
        med_log_b - 0.22 * float(np.median(logd)),
        0.0, 0.22,
        0.25,
    ], dtype=float)
    return _fit_generic(X, y, init, unpack, _lrbsz_predict, n_restarts=7, use_log=True)


# ---- Data-constrained law with sublinear repeat utility ----------------
# Effective tokens grow linearly when D << U, but only as a power law once data
# are repeated: D_eff ~ U^(1-r) D^r for D >> U.

def _dconstrained_predict(X, params):
    u = np.clip(np.asarray(X[:, 0], dtype=float), 1.0, None)
    n = np.clip(np.asarray(X[:, 1], dtype=float), 1.0, None)
    d = np.clip(np.asarray(X[:, 2], dtype=float), 1.0, None)
    E, A, alpha, B, beta, r, C, gamma = params
    ratio = np.clip(d / u, 0.0, 1e6)
    if r < 1e-4:
        d_eff = u * np.log1p(ratio)
    else:
        d_eff = u * ((1.0 + ratio) ** r - 1.0) / r
    d_eff = np.maximum(d_eff, 1.0)
    return E + A * np.power(n, -alpha) + B * np.power(d_eff, -beta) + C * np.power(u, -gamma)



def _fit_dconstrained(X, y):
    y = np.asarray(y, dtype=float)

    def unpack(u):
        r = np.clip(_sigmoid(u[5]), 1e-4, 0.999)
        return np.array([
            np.exp(u[0]),
            np.exp(u[1]), np.exp(u[2]),
            np.exp(u[3]), np.exp(u[4]),
            r,
            np.exp(u[6]), np.exp(u[7]),
        ], dtype=float)

    init = np.array([
        np.log(max(y.min() * 0.9, 0.1)),
        np.log(max(y.max() - y.min(), 0.1)), np.log(0.35),
        np.log(max(y.max() - y.min(), 0.1)), np.log(0.28),
        -0.7,
        np.log(max((y.max() - y.min()) * 0.3, 0.05)), np.log(0.25),
    ], dtype=float)
    return _fit_generic(X, y, init, unpack, _dconstrained_predict, n_restarts=8, use_log=True)


class ScalingLawModel:
    """Benchmark-specific bottleneck-renormalized scaling laws.

    Novel contribution:
    - vocab: learn a vocab-induced data renormalization D_eff = D / V^phi
    - lrbsz: fit a coupled lr/batch optimum manifold instead of independent bowls
    - dataconstrained: use a soft power-law repeat utility for D >> U
    """

    def __init__(self, benchmark_name: str, numeric_names=None, categorical_names=None):
        self.benchmark_name = benchmark_name
        self.numeric_names = list(numeric_names or [])
        self.categorical_names = list(categorical_names or [])
        self.group_params_ = {}
        self.default_params_ = None
        self.num_features_ = 0

    def _fit_one(self, X, y):
        if self.benchmark_name == "sld-vocab":
            return _fit_vocab(X, y)
        if self.benchmark_name == "sld-lrbsz":
            return _fit_lrbsz(X, y)
        if self.benchmark_name == "sld-dataconstrained":
            return _fit_dconstrained(X, y)
        raise ValueError(f"Unknown benchmark: {self.benchmark_name}")

    def _predict_one(self, X, params):
        if self.benchmark_name == "sld-vocab":
            return _vocab_predict(X, params)
        if self.benchmark_name == "sld-lrbsz":
            return _lrbsz_predict(X, params)
        if self.benchmark_name == "sld-dataconstrained":
            return _dconstrained_predict(X, params)
        raise ValueError(f"Unknown benchmark: {self.benchmark_name}")

    def fit(self, X_num, X_cat, y):
        X_num = np.asarray(X_num, dtype=float)
        y = np.asarray(y, dtype=float)
        labels = group_labels(X_cat)
        fitted = []
        for group in sorted(set(labels.tolist())):
            mask = labels == group
            params = self._fit_one(X_num[mask], y[mask])
            self.group_params_[group] = params
            fitted.append(params)
        self.default_params_ = np.median(np.stack(fitted, axis=0), axis=0)
        self.num_features_ = int(len(self.default_params_))
        return self

    def predict(self, X_num, X_cat):
        X_num = np.asarray(X_num, dtype=float)
        labels = group_labels(X_cat)
        preds = np.zeros(len(labels), dtype=float)
        for group in sorted(set(labels.tolist())):
            mask = labels == group
            params = self.group_params_.get(group, self.default_params_)
            preds[mask] = self._predict_one(X_num[mask], params)
        return preds


